def count_Pairs(nums, n):
    if len(nums) != n:
        raise ValueError("Length of nums must match n")

    from collections import Counter
    freq = Counter(nums)
    total_pairs = 0

    for x in freq:
        c_x = freq[x]
        # Pairs with one element equal to x and the other not equal to x
        count_not_x = n - c_x
        if count_not_x > 0:
            total_pairs += c_x * count_not_x

    return total_pairs // 2
